-- Full Schema v5 + Seed for ScholarshipHive Processing Portal
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `activity_log`;
CREATE TABLE `activity_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned DEFAULT NULL,
  `student_id` int(10) unsigned DEFAULT NULL,
  `action` varchar(255) NOT NULL,
  `ip` varchar(45) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_student` (`student_id`),
  KEY `idx_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=458 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `app_settings`;
CREATE TABLE `app_settings` (
  `k` varchar(60) NOT NULL,
  `v` text DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`k`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `applications`;
CREATE TABLE `applications` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `import_key` varchar(80) DEFAULT NULL,
  `student_id` int(10) unsigned NOT NULL,
  `list_name` varchar(60) DEFAULT NULL,
  `sort_no` varchar(10) DEFAULT NULL,
  `university` varchar(255) DEFAULT NULL,
  `program` text DEFAULT NULL,
  `app_type` varchar(150) DEFAULT NULL,
  `deadline` varchar(150) DEFAULT NULL,
  `requirements` text DEFAULT NULL,
  `fee` varchar(100) DEFAULT NULL,
  `applied_date` varchar(60) DEFAULT NULL,
  `status` varchar(255) DEFAULT NULL,
  `result` varchar(30) DEFAULT NULL,
  `link` text DEFAULT NULL,
  `submitted_by` varchar(60) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `updated_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  `nostrification_status` varchar(100) DEFAULT NULL,
  `nostrification_fee` varchar(100) DEFAULT NULL,
  `starting` varchar(100) DEFAULT NULL,
  `language` varchar(255) DEFAULT NULL,
  `portal_id` varchar(150) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_app_import` (`import_key`),
  KEY `idx_app_student` (`student_id`),
  CONSTRAINT `fk_app_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=436 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `import_notes`;
CREATE TABLE `import_notes` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` int(10) unsigned DEFAULT NULL,
  `country` varchar(20) DEFAULT NULL,
  `sheet` varchar(120) NOT NULL,
  `ref` varchar(40) DEFAULT NULL,
  `field` varchar(60) DEFAULT NULL,
  `note` text NOT NULL,
  `resolved` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_note_student` (`student_id`),
  CONSTRAINT `fk_note_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `login_attempts`;
CREATE TABLE `login_attempts` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `ip` varchar(45) NOT NULL,
  `username` varchar(80) NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ip` (`ip`,`created_at`),
  KEY `idx_user` (`username`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `student_documents`;
CREATE TABLE `student_documents` (
  `student_id` int(10) unsigned NOT NULL,
  `doc_key` varchar(40) NOT NULL DEFAULT '',
  `status` varchar(12) NOT NULL,
  `updated_by` int(10) unsigned DEFAULT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`student_id`,`doc_key`),
  CONSTRAINT `fk_docs_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `student_files`;
CREATE TABLE `student_files` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` int(10) unsigned NOT NULL,
  `doc_key` varchar(40) NOT NULL DEFAULT 'other',
  `meeting_id` int(10) unsigned DEFAULT NULL,
  `original_name` varchar(255) NOT NULL,
  `stored_name` varchar(120) NOT NULL,
  `mime` varchar(100) NOT NULL,
  `size` int(10) unsigned NOT NULL,
  `uploaded_by` int(10) unsigned DEFAULT NULL,
  `uploaded_role` varchar(12) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `file_hash` varchar(64) DEFAULT NULL,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_file_student_stored` (`student_id`,`doc_key`,`stored_name`),
  KEY `idx_file_student` (`student_id`,`doc_key`),
  KEY `idx_file_meeting` (`meeting_id`),
  CONSTRAINT `fk_file_meeting` FOREIGN KEY (`meeting_id`) REFERENCES `student_meetings` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_file_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4419 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `student_followups`;
CREATE TABLE `student_followups` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `student_id` int(11) NOT NULL,
  `what_pending` text NOT NULL,
  `last_followup_date` date NOT NULL,
  `message_sent` text DEFAULT NULL,
  `student_reply` text DEFAULT NULL,
  `next_followup_date` date DEFAULT NULL,
  `status` enum('Pending','In Progress','Resolved') NOT NULL DEFAULT 'Pending',
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_std` (`student_id`),
  KEY `idx_due` (`next_followup_date`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=75 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `student_meetings`;
CREATE TABLE `student_meetings` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` int(10) unsigned NOT NULL,
  `kind` varchar(20) NOT NULL DEFAULT 'other',
  `title` varchar(150) NOT NULL,
  `meeting_date` date DEFAULT NULL,
  `meeting_time` varchar(10) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'Scheduled',
  `join_link` varchar(500) DEFAULT NULL,
  `recording_link` varchar(500) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `student_can_see` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  `meeting_type` varchar(30) DEFAULT NULL,
  `location` varchar(150) DEFAULT NULL,
  `staff_member` varchar(150) DEFAULT NULL,
  `recording_available` varchar(10) DEFAULT NULL,
  `recording_upload_status` varchar(30) DEFAULT NULL,
  `exception_reason` text DEFAULT NULL,
  `exception_authorized_by` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_meet_student` (`student_id`,`meeting_date`),
  CONSTRAINT `fk_meet_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=110 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `student_progress_logs`;
CREATE TABLE `student_progress_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `student_id` int(11) NOT NULL,
  `officer_id` int(11) DEFAULT NULL,
  `officer_name` varchar(150) DEFAULT NULL,
  `log_date` date NOT NULL,
  `progress_note` text NOT NULL,
  `action_type` varchar(100) DEFAULT 'Daily Progress',
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_std` (`student_id`),
  KEY `idx_date` (`log_date`)
) ENGINE=InnoDB AUTO_INCREMENT=169 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `student_tasks`;
CREATE TABLE `student_tasks` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` int(10) unsigned NOT NULL,
  `task_type` varchar(50) NOT NULL,
  `title` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `assigned_to` int(10) unsigned DEFAULT NULL,
  `assigned_team` varchar(20) DEFAULT NULL,
  `due_date` date DEFAULT NULL,
  `priority` enum('high','medium','low') NOT NULL DEFAULT 'medium',
  `status` enum('pending','in_progress','completed','cancelled') NOT NULL DEFAULT 'pending',
  `auto_generated` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_task_student` (`student_id`),
  KEY `idx_task_status` (`status`),
  KEY `idx_task_assigned` (`assigned_to`),
  CONSTRAINT `fk_task_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `students`;
CREATE TABLE `students` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `import_key` varchar(60) DEFAULT NULL,
  `country` varchar(20) NOT NULL DEFAULT 'italy',
  `sr_no` int(11) DEFAULT NULL,
  `process_status` varchar(30) DEFAULT NULL,
  `name` varchar(150) NOT NULL,
  `counselor` varchar(150) DEFAULT NULL,
  `officer_id` int(10) unsigned DEFAULT NULL,
  `entered_by` int(10) unsigned DEFAULT NULL,
  `refund` varchar(60) DEFAULT NULL,
  `refund_reason` varchar(255) DEFAULT NULL,
  `dues` varchar(60) DEFAULT NULL,
  `branch` varchar(100) DEFAULT NULL,
  `intake` varchar(60) DEFAULT NULL,
  `received_date` date DEFAULT NULL,
  `study_level` varchar(40) DEFAULT NULL,
  `applied_for` varchar(255) DEFAULT NULL,
  `last_degree` varchar(255) DEFAULT NULL,
  `gpa` varchar(100) DEFAULT NULL,
  `ielts` varchar(60) DEFAULT NULL,
  `contact_no` varchar(60) DEFAULT NULL,
  `client_type` varchar(30) DEFAULT NULL,
  `consult1` varchar(40) DEFAULT NULL,
  `consent` varchar(30) DEFAULT NULL,
  `docs_checklist` varchar(30) DEFAULT NULL,
  `initial_meeting` varchar(40) DEFAULT NULL,
  `follow_up_1` date DEFAULT NULL,
  `recorded_uploaded` varchar(40) DEFAULT NULL,
  `drive_link` text DEFAULT NULL,
  `recording_note` varchar(500) DEFAULT NULL,
  `meeting_priority` varchar(30) DEFAULT NULL,
  `meeting_date` date DEFAULT NULL,
  `second_meeting` varchar(30) DEFAULT NULL,
  `follow_up_2` date DEFAULT NULL,
  `tax_meeting` varchar(30) DEFAULT NULL,
  `follow_up_3` date DEFAULT NULL,
  `tax_remarks` text DEFAULT NULL,
  `tax_recording_link` varchar(500) DEFAULT NULL,
  `offer` varchar(30) DEFAULT NULL,
  `consult2` varchar(40) DEFAULT NULL,
  `disc2` text DEFAULT NULL,
  `enrollment` varchar(30) DEFAULT NULL,
  `consult3` varchar(40) DEFAULT NULL,
  `disc3` text DEFAULT NULL,
  `visa` varchar(30) DEFAULT NULL,
  `last_installment` varchar(150) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `remarks_date` date DEFAULT NULL,
  `back_officer_id` int(10) unsigned DEFAULT NULL,
  `documents_status` varchar(255) DEFAULT NULL,
  `pending_documents` text DEFAULT NULL,
  `documents_link` text DEFAULT NULL,
  `doc_request_date` date DEFAULT NULL,
  `student_email` varchar(150) DEFAULT NULL,
  `recovery_email` varchar(150) DEFAULT NULL,
  `email_password_enc` text DEFAULT NULL,
  `portal_id` varchar(150) DEFAULT NULL,
  `portal_password_enc` text DEFAULT NULL,
  `cv_status` varchar(30) DEFAULT NULL,
  `sop_status` varchar(30) DEFAULT NULL,
  `campus_france` varchar(255) DEFAULT NULL,
  `mock_interview` varchar(30) DEFAULT NULL,
  `shortlisting` varchar(60) DEFAULT NULL,
  `shortlisted_course` varchar(255) DEFAULT NULL,
  `admission_university` varchar(255) DEFAULT NULL,
  `application_fees` varchar(100) DEFAULT NULL,
  `application_status` varchar(255) DEFAULT NULL,
  `admission_letters` varchar(100) DEFAULT NULL,
  `embassy_status` varchar(100) DEFAULT NULL,
  `legalization_status` varchar(60) DEFAULT NULL,
  `second_consultancy` varchar(100) DEFAULT NULL,
  `application_notes` text DEFAULT NULL,
  `record_remarks` text DEFAULT NULL,
  `record_remarks_date` date DEFAULT NULL,
  `enrollment_summary_status` varchar(150) DEFAULT NULL,
  `enrollment_summary_date` date DEFAULT NULL,
  `inst1` varchar(20) DEFAULT NULL,
  `inst2` varchar(20) DEFAULT NULL,
  `inst3` varchar(20) DEFAULT NULL,
  `inst4` varchar(20) DEFAULT NULL,
  `refund_threat` text DEFAULT NULL,
  `back_remarks` text DEFAULT NULL,
  `back_remarks_date` date DEFAULT NULL,
  `embassy` varchar(150) DEFAULT NULL,
  `visa_checklist_shared` varchar(20) DEFAULT NULL,
  `visa_checklist_date` date DEFAULT NULL,
  `sponsor` varchar(255) DEFAULT NULL,
  `financial_verified` varchar(20) DEFAULT NULL,
  `financial_missing` text DEFAULT NULL,
  `cimea_received` varchar(20) DEFAULT NULL,
  `cimea_date` date DEFAULT NULL,
  `visa_form_by` varchar(20) DEFAULT NULL,
  `health_insurance` varchar(20) DEFAULT NULL,
  `flight_hotel` varchar(20) DEFAULT NULL,
  `appointment_status` varchar(30) DEFAULT NULL,
  `appointment_date` date DEFAULT NULL,
  `visa_submitted_date` date DEFAULT NULL,
  `email_checked_date` date DEFAULT NULL,
  `visa_decision_date` date DEFAULT NULL,
  `visa_remarks` text DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  `total_package_fee` varchar(40) DEFAULT NULL,
  `total_paid` varchar(40) DEFAULT NULL,
  `balance_due` varchar(40) DEFAULT NULL,
  `payment_status` varchar(40) DEFAULT NULL,
  `draft_step` int(10) unsigned NOT NULL DEFAULT 1,
  `is_draft` tinyint(1) NOT NULL DEFAULT 0,
  `cas_number` varchar(100) DEFAULT NULL,
  `tb_test_status` varchar(30) DEFAULT NULL,
  `aps_number` varchar(100) DEFAULT NULL,
  `coe_number` varchar(100) DEFAULT NULL,
  `pal_status` varchar(100) DEFAULT NULL,
  `gic_status` varchar(100) DEFAULT NULL,
  `nostrification_status` varchar(100) DEFAULT NULL,
  `initial_meeting_mode` varchar(30) DEFAULT NULL,
  `tax_meeting_mode` varchar(30) DEFAULT NULL,
  `second_meeting_mode` varchar(30) DEFAULT NULL,
  `shortlisting_shared` varchar(150) DEFAULT NULL,
  `updated_by` int(10) unsigned DEFAULT NULL,
  `documents_note` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_import` (`import_key`),
  KEY `idx_officer` (`officer_id`),
  KEY `idx_back_officer` (`back_officer_id`),
  KEY `idx_name` (`name`),
  KEY `fk_students_entered` (`entered_by`),
  KEY `idx_country` (`country`),
  CONSTRAINT `fk_students_back_officer` FOREIGN KEY (`back_officer_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_students_entered` FOREIGN KEY (`entered_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_students_officer` FOREIGN KEY (`officer_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=373 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) NOT NULL,
  `username` varchar(80) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `role` enum('admin','subadmin','officer','tax','student') NOT NULL,
  `team` enum('frontend','backend') DEFAULT NULL,
  `countries` varchar(150) DEFAULT NULL,
  `student_id` int(10) unsigned DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `must_change_password` tinyint(1) NOT NULL DEFAULT 1,
  `last_login` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_username` (`username`),
  UNIQUE KEY `uq_student` (`student_id`),
  CONSTRAINT `fk_users_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=382 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SET FOREIGN_KEY_CHECKS = 1;
